// Icons.tsx
import * as React from "react";
import Svg, { Path, G, Defs, ClipPath, Rect, SvgProps } from "react-native-svg";
import { useTheme } from '@/theme/ThemeContext';
import { ColorValue } from "react-native";

// Helper function to safely convert ColorValue to string
const safeColor = (color: ColorValue | undefined, fallback: string): string => {
  if (!color) return fallback;
  if (typeof color === 'string') return color;
  // For OpaqueColorValue, we need to handle it differently
  // In practice, we'll just use the fallback for non-string colors
  return fallback;
};

// Reusable hook for icon color
const useIconColor = (color?: ColorValue) => {
  const { theme } = useTheme();
  return safeColor(color, theme.colors.brandPrimary);
};

const useAccentColor = (color?: ColorValue) => {
  const { theme } = useTheme();
  return safeColor(color, theme.colors.brandAccent);
};

